import java.util.*;

public class Main {
    static int[] denoms = {500, 100, 50, 10};

    static int computeChange(int amount, boolean[] available) {
        if (amount == 0) return 0;
        int coins = 0;
        for (int d : denoms) {
            int idx = denomIndex(d);
            if (available[idx]) {
                int use = amount / d;
                coins += use;
                amount -= use * d;
            }
        }
        if (amount != 0) return Integer.MAX_VALUE; // can't make change
        return coins;
    }

    static int denomIndex(int d) {
        if (d == 500) return 0;
        if (d == 100) return 1;
        if (d == 50) return 2;
        return 3; // 10
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int price = sc.nextInt();
            if (price == 0) break;
            int[] have = new int[4]; // 500,100,50,10
            for (int i = 0; i < 4; i++) have[i] = sc.nextInt();

            int totalHave = have[0]+have[1]+have[2]+have[3];
            int best = Integer.MAX_VALUE;
            int[] bestUse = null;

            for (int u0 = 0; u0 <= have[0]; u0++)
            for (int u1 = 0; u1 <= have[1]; u1++)
            for (int u2 = 0; u2 <= have[2]; u2++)
            for (int u3 = 0; u3 <= have[3]; u3++) {
                int payment = u0*500 + u1*100 + u2*50 + u3*10;
                if (payment < price) continue;
                int change = payment - price;
                boolean[] avail = new boolean[4];
                avail[0] = (u0 == 0);
                avail[1] = (u1 == 0);
                avail[2] = (u2 == 0);
                avail[3] = (u3 == 0);
                int changeCoins = computeChange(change, avail);
                if (changeCoins == Integer.MAX_VALUE) continue;
                int used = u0+u1+u2+u3;
                int finalCoins = totalHave - used + changeCoins;
                if (finalCoins < best) {
                    best = finalCoins;
                    bestUse = new int[]{u0,u1,u2,u3};
                }
            }
            System.out.println(bestUse[0]+" "+bestUse[1]+" "+bestUse[2]+" "+bestUse[3]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int[] VAL = {10, 50, 100, 500};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while (true) {
            int[] have = new int[4];
            int filled = 0;

            while (filled < 4) {
                line = br.readLine();
                if (line == null) {
                    System.out.print(out.toString());
                    return;
                }
                line = line.trim();
                if (line.isEmpty()) continue;
                StringTokenizer st = new StringTokenizer(line);
                while (st.hasMoreTokens() && filled < 4) {
                    have[filled++] = Integer.parseInt(st.nextToken());
                }
            }

            int price = -1;
            while (price == -1) {
                line = br.readLine();
                if (line == null) {
                    System.out.print(out.toString());
                    return;
                }
                line = line.trim();
                if (line.isEmpty()) continue;
                price = Integer.parseInt(line);
            }

            if (have[0] == 0 && have[1] == 0 && have[2] == 0 && have[3] == 0 && price == 0) break;

            int[] bestPay = solve(have, price);

            for (int i = 0; i < 4; i++) {
                if (bestPay[i] > 0) {
                    out.append(VAL[i]).append(' ').append(bestPay[i]).append('\n');
                }
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }

    static int[] solve(int[] have, int price) {
        int maxSum = 0;
        for (int i = 0; i < 4; i++) maxSum += have[i] * VAL[i];

        int bestRemain = Integer.MAX_VALUE;
        int bestPaid = Integer.MAX_VALUE;
        int[] best = new int[4];

        for (int a = 0; a <= have[0]; a++) {
            int sumA = a * 10;
            for (int b = 0; b <= have[1]; b++) {
                int sumB = sumA + b * 50;
                for (int c = 0; c <= have[2]; c++) {
                    int sumC = sumB + c * 100;
                    for (int d = 0; d <= have[3]; d++) {
                        int pay = sumC + d * 500;
                        if (pay < price) continue;

                        int change = pay - price;

                        // Cannot receive same type of coin as used for payment.
                        if (!validChange(change, a, b, c, d)) continue;

                        int remain = (have[0] - a) + (have[1] - b) + (have[2] - c) + (have[3] - d)
                                + minCoins(change);

                        if (remain < bestRemain || (remain == bestRemain && pay < bestPaid)) {
                            bestRemain = remain;
                            bestPaid = pay;
                            best[0] = a;
                            best[1] = b;
                            best[2] = c;
                            best[3] = d;
                        }
                    }
                }
            }
        }
        return best;
    }

    static boolean validChange(int change, int a, int b, int c, int d) {
        int[] ch = greedyChange(change);
        if (a > 0 && ch[0] > 0) return false;
        if (b > 0 && ch[1] > 0) return false;
        if (c > 0 && ch[2] > 0) return false;
        if (d > 0 && ch[3] > 0) return false;
        return true;
    }

    static int minCoins(int change) {
        int cnt = 0;
        cnt += change / 500;
        change %= 500;
        cnt += change / 100;
        change %= 100;
        cnt += change / 50;
        change %= 50;
        cnt += change / 10;
        return cnt;
    }

    static int[] greedyChange(int change) {
        int[] ch = new int[4];
        ch[3] = change / 500;
        change %= 500;
        ch[2] = change / 100;
        change %= 100;
        ch[1] = change / 50;
        change %= 50;
        ch[0] = change / 10;
        return ch;
    }
}

