    vector<int> wallet = {a, b, c, d}; // counts of 10,50,100,500 yen

    // dp[10][50][100][500] = minimal coins after change, but we'll use DP over total value
    // Since total coins are small, we can brute force all possible payment combinations

    int best_use[4] = {0,0,0,0};
    int best_remaining = INF;

    // iterate over how many of each coin to use
    for (int u10 = 0; u10 <= a; ++u10) {
        for (int u50 = 0; u50 <= b; ++u50) {
            for (int u100 = 0; u100 <= c; ++u100) {
                for (int u500 = 0; u500 <= d; ++u500) {
                    int paid = u10*10 + u50*50 + u100*100 + u500*500;
                    if (paid < p) continue;

                    int change = paid - p;
                    // We need to give change using coins not used in payment
                    // available coins for change: all wallet coins except those used
                    vector<int> avail = {a - u10, b - u50, c - u100, d - u500};

                    // Greedy for change: since clerk uses optimal change (standard coin system greedy works)
                    int change_coins = 0;
                    int temp = change;
                    vector<int> used_change(4,0);
                    for (int i = 3; i >= 0; --i) {
                        int coin = coins[i];
                        int cnt = min(avail[i], temp / coin);
                        used_change[i] = cnt;
                        temp -= cnt * coin;
                        change_coins += cnt;
                    }
                    if (temp != 0) continue; // cannot make exact change with available coins

                    // But also need to ensure that we don't give back same type as used? 
                    // Actually problem says: "it's not allowed to receive the same type of coin back as change that was used for payment"
                    // So if we used a coin type, we cannot get that type back.
                    // Check this condition:
                    bool ok = true;
                    for (int i = 0; i < 4; ++i) {
                        if (u10>0 && i==0 && used_change[i]>0) ok = false;
                        if (u50>0 && i==1 && used_change[i]>0) ok = false;
                        if (u100>0 && i==2 && used_change[i]>0) ok = false;
                        if (u500>0 && i==3 && used_change[i]>0) ok = false;
                    }
                    if (!ok) continue;

                    // total coins after payment = (coins left in wallet) + (change coins received)
                    int remaining = (a - u10) + (b - u50) + (c - u100) + (d - u500) + change_coins;
                    if (remaining < best_remaining) {
                        best_remaining = remaining;
                        best_use[0] = u10;
                        best_use[1] = u50;
                        best_use[2] = u100;
                        best_use[3] = u500;
                    }
                }
            }
        }
    }

    // Output
    for (int i = 0; i < 4; ++i) {
        cout << best_use[i] << (i==3 ? '\n' : ' ');
    }

    return 0;
