    // total money we have
    int total_money = 0;
    for (int i = 0; i < 4; i++) {
        total_money += coins[i] * values[i];
    }

    // We need to pay at least price, but cannot exceed total_money
    // We want to minimize remaining coins after optimal change.
    // Equivalent to: choose a subset of coins to pay such that after
    // optimal change (clerk gives back minimal number of coins without
    // giving back same type as used), the number of coins left is minimized.

    // Since constraints are small (max coins: unknown but reasonable),
    // we can brute force over possible numbers of each coin to use.

    int best_remaining = 1e9;
    int best_use[4] = {0};

    for (int u10 = 0; u10 <= coins[0]; u10++) {
        for (int u50 = 0; u50 <= coins[1]; u50++) {
            for (int u100 = 0; u100 <= coins[2]; u100++) {
                for (int u500 = 0; u500 <= coins[3]; u500++) {
                    int paid = u10*10 + u50*50 + u100*100 + u500*500;
                    if (paid < price) continue;

                    int change_needed = paid - price;

                    // Clerk gives change optimally using 500,100,50,10
                    // but cannot give back the same type that was used.
                    // So for each type, the clerk can use at most
                    // (clerk's supply is unlimited? Actually problem says
                    // clerk gives change optimally, but doesn't mention
                    // limited supply. So assume unlimited except restriction
                    // that they cannot give back a coin type that was used.)
                    // So clerk's available coins for change are all types
                    // except those we used.

                    int clerk_avail[4] = {1,1,1,1};
                    if (u10 > 0) clerk_avail[0] = 0;
                    if (u50 > 0) clerk_avail[1] = 0;
                    if (u100 > 0) clerk_avail[2] = 0;
                    if (u500 > 0) clerk_avail[3] = 0;

                    // Greedy change: use largest denomination first
                    int change_coins = 0;
                    int remaining = change_needed;
                    for (int i = 3; i >= 0; i--) {
                        if (clerk_avail[i]) {
                            int cnt = remaining / values[i];
                            change_coins += cnt;
                            remaining -= cnt * values[i];
                        }
                    }
                    if (remaining != 0) continue; // cannot make exact change? but with unlimited coins except restriction, if all types blocked might fail. But if we use all types, clerk has no coins, so change must be 0 => paid==price.

                    // After payment and change:
                    // Coins left = (original - used) + change_coins
                    int left_coins = (coins[0]-u10)+(coins[1]-u50)+(coins[2]-u100)+(coins[3]-u500) + change_coins;

                    if (left_coins < best_remaining) {
                        best_remaining = left_coins;
                        best_use[0] = u10;
                        best_use[1] = u50;
                        best_use[2] = u100;
                        best_use[3] = u500;
                    }
                }
            }
        }
    }

    printf("%d\n%d\n%d\n%d\n", best_use[0], best_use[1], best_use[2], best_use[3]);

    return 0;
}

#include <stdio.h>
#include <limits.h>

int change_coins(int amount, int use10, int use50, int use100, int use500) {
    // denominations available: those NOT used by bill
    int denoms[4] = {500, 100, 50, 10};
    int used[4] = {use500, use100, use50, use10};
    int coins = 0;
    for (int i = 0; i < 4; i++) {
        if (used[i]) continue; // can't use this denomination
        int c = amount / denoms[i];
        coins += c;
        amount -= c * denoms[i];
    }
    if (amount != 0) return INT_MAX; // can't make change
    return coins;
}

