import sys

def solve():
    data = list(map(int, sys.stdin.read().split()))
    if len(data) != 5:
        return

    c10, c50, c100, c500, price = data
    vals = [10, 50, 100, 500]
    have = [c10, c50, c100, c500]

    max_pay = c10 * 10 + c50 * 50 + c100 * 100 + c500 * 500

    # Precompute optimal change coin counts for all amounts up to max possible overpay.
    # Change is given only with coins, optimally, and cannot include a denomination used in payment.
    # Since denominations are canonical, greedy is optimal.
    best_change = {}
    for mask in range(16):
        allowed = []
        for i in range(4):
            if not (mask >> i) & 1:
                allowed.append(vals[i])
        # dp over amounts with allowed denominations
        INF = 10**9
        dp = [INF] * (max_pay + 1)
        dp[0] = 0
        for a in range(1, max_pay + 1):
            for v in allowed:
                if a >= v and dp[a - v] + 1 < dp[a]:
                    dp[a] = dp[a - v] + 1
        best_change[mask] = dp

    best_total = 10**18
    best_use = None

    for a in range(c10 + 1):
        pay10 = a * 10
        for b in range(c50 + 1):
            pay50 = pay10 + b * 50
            if pay50 > max_pay:
                break
            for c in range(c100 + 1):
                pay100 = pay50 + c * 100
                if pay100 > max_pay:
                    break
                # Need d such that payment >= price
                need = price - pay100
                d_min = 0 if need <= 0 else (need + 499) // 500
                if d_min > c500:
                    continue
                for d in range(d_min, c500 + 1):
                    payment = pay100 + d * 500
                    change = payment - price

                    mask = 0
                    if a > 0: mask |= 1 << 0
                    if b > 0: mask |= 1 << 1
                    if c > 0: mask |= 1 << 2
                    if d > 0: mask |= 1 << 3

                    ch = best_change[mask][change]
                    if ch >= 10**9:
                        continue

                    used = a + b + c + d
                    remain_before_change = (c10 - a) + (c50 - b) + (c100 - c) + (c500 - d)
                    total_after = remain_before_change + ch

                    if total_after < best_total:
                        best_total = total_after
                        best_use = [a, b, c, d]

    if best_use is None:
        return

    print(*best_use)

